function top_names(players, n)
  local copy = {}
  for i, v in ipairs(players) do copy[i] = v end
  table.sort(copy, function(a, b) return a.score > b.score end)
  local out = {}
  local limit = math.min(n, #copy)
  for i = 1, limit do out[i] = copy[i].name end
  return out
end

