local Counter = {}
Counter.__index = Counter

function Counter.new(start)
  return setmetatable({value = start or 0}, Counter)
end

function Counter:inc(step)
  self.value = self.value + (step or 1)
  return self.value
end

local c = Counter.new(10)
print(c:inc(), c:inc(5))
print(Counter.new().value)

